function handleMessage(data) {
    if (data) {
        let message = "";
        if (typeof data.message == "string") {
            message = titleCase(data.message);
        } else if (data.message && typeof data.message === "object") {
            message = Object.values(data.message).flat();
            let uniqueMessage = [...new Set(message)];
            message = uniqueMessage.map((msg) => titleCase(msg)).join("</br>");
        }

        if (!message || message.trim() === "") {
            return;
        }

        toastr.options = {
            positionClass: "toast-bottom-right",
            allowHtml: true,
            closeButton: true,
            timeOut: 3000,
        };

        if (data.success == "warning") {
            toastr.warning(message);
        } else if (data.success == "info") {
            toastr.info(message);
        } else if (data.success) {
            toastr.success(message);
        } else {
            toastr.error(message);
        }
    }
}

function alertMessage(data) {
    if (data) {
        let message = "";
        if (typeof data.message == "string") {
            message = titleCase(data.message);
        } else if (data.message && typeof data.message === "object") {
            message = Object.values(data.message).flat();
            let uniqueMessage = [...new Set(message)];
            message = uniqueMessage.map((msg) => titleCase(msg)).join("</br>");
        }

        toastr.options = {
            positionClass: "toast-bottom-right",
            allowHtml: true,
            closeButton: true,
            timeOut: 10000,
        };

        if (data.success) {
            toastr.success(message);
        } else {
            toastr.error(message);
        }
    }
}

function titleCase(string) {
    return string[0].toUpperCase() + string.slice(1).toLowerCase();
}

function getContrastTextColor(hexBgColor) {
    let hex = hexBgColor.replace("#", "");

    if (hex.length === 3) {
        hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
    }

    let r = parseInt(hex.substring(0, 2), 16) / 255;
    let g = parseInt(hex.substring(2, 4), 16) / 255;
    let b = parseInt(hex.substring(4, 6), 16) / 255;

    r = r <= 0.03928 ? r / 12.92 : Math.pow((r + 0.055) / 1.055, 2.4);
    g = g <= 0.03928 ? g / 12.92 : Math.pow((g + 0.055) / 1.055, 2.4);
    b = b <= 0.03928 ? b / 12.92 : Math.pow((b + 0.055) / 1.055, 2.4);

    const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;

    return luminance > 0.5 ? "#212529" : "#ffffff";
}

function formatMoney(n) {
    if (n == null) {
        return 0;
    }
    if (typeof n !== "string") {
        n = n.toString();
    }

    n = n.replace(/\D/g, "");

    if (n.charAt(0) == "0") {
        n = n.slice(1);
    }

    if (n == "") {
        n = "0";
    }

    return n.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function formatMoney2(n) {
    if (typeof n !== "string") {
        n = n.toString();
    }

    // Nếu không đúng định dạng số thực thì làm sạch lại
    let parts = n.match(/^\d*\.?\d*$/) ? n : "";

    if (parts === "") {
        let firstDotIndex = n.indexOf(".");
        if (firstDotIndex !== -1) {
            let integerPart = n.slice(0, firstDotIndex).replace(/\D/g, "");
            let decimalPart = n.slice(firstDotIndex + 1).replace(/\D/g, "");
            n = integerPart + (decimalPart ? "." + decimalPart : "");
        } else {
            n = n.replace(/\D/g, "");
        }
    }

    let [integerPart, decimalPart] = n.split(".");

    if (integerPart.length > 1) {
        integerPart = integerPart.replace(/^0+/, "");
        if (integerPart === "") integerPart = "0";
    }

    integerPart = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, ",");

    // ❌ Nếu decimalPart là 00 hoặc không tồn tại => bỏ
    if (!decimalPart || parseInt(decimalPart) === 0) {
        return integerPart;
    }

    // ✅ Nếu decimalPart khác 00 => giữ lại
    return integerPart + "." + decimalPart;
}

function parseFormattedNumber(str) {
    if (!str) return 0;

    // Xoá dấu phẩy (ngăn cách hàng nghìn)
    str = str.replace(/,/g, "");

    // Giữ dấu chấm để parseFloat hiểu là thập phân
    return parseFloat(str);
}

$(document).on("keypress", 'input[type="number"]', function (e) {
    if (e.which != 8 && e.which != 0 && (e.which < 48 || e.which > 57)) {
        return false;
    }
});

$(document).on("change keyup", 'input[type="number"]', function (e) {
    let value = parseFloat($(this).val());
    if (value < 0) {
        $(this).val(0);
    }
});

$(document).on("keypress", "input.input-price", function (e) {
    if (e.which != 8 && e.which != 0 && (e.which < 48 || e.which > 57)) {
        return false;
    }
});

$(document).on("change keyup", "input.input-price", function (e) {
    let value = parseFloat(
        $(this)
            .val()
            .replace(/[^0-9\.]/gi, ""),
    );
    if (value < 0) {
        $(this).val(0);
    } else {
        $(this).val(formatMoney(value));
    }
});

$(".collapse").on("show.bs.collapse", function () {
    $(this).siblings(".decen_item_gr , .itemCollapse").addClass("rotate-90");
});

$(".collapse").on("hide.bs.collapse", function () {
    $(this).siblings(".decen_item_gr , .itemCollapse").removeClass("rotate-90");
});

