$(document).on("click", function (e) {
    if (!$(e.target).closest("#dropdown-language, #languageBtn").length) {
        $("#dropdown-language").css("display", "none");
    }

    if (!$(e.target).closest("#dropdown-profile, .menu ").length) {
        $(".menu").removeClass("active");
    }
});
$("#languageBtn").on("click", function (e) {
    const display = $("#dropdown-language").css("display");
    if (display === "none") {
        $("#dropdown-language").css("display", "block");
    } else {
        $("#dropdown-language").css("display", "none");
    }
});
