    //     let alertText = "Đang test, chờ tí ..."
    //     alertText += "isStandalone: " + isStandalone + "\n";
    //     alertText += "isAndroid: " + isAndroid + "\n";
    //     alertText += "isIOS: " + isIOS + "\n";
