$(document).on("click", ".btn-open-modal", function () {
    const dataOffcanvasTarget = $(this).data("offcanvas-target");
    const offcanvasBottomInMobileLabel = $("#offcanvasBottomInMobileLabel");
    const dataOffcanvasLabel = $(this).find(".open-modal-label")?.text() || "";

    $("#offcanvasBottomInMobile .offcanvas-body")?.append(
        $(dataOffcanvasTarget).find(".inner-modal-in-mobile"),
    );

    $("#offcanvasBottomInMobile").attr(
        "data-destination-offcanvas-target",
        dataOffcanvasTarget,
    );

    offcanvasBottomInMobileLabel.text(dataOffcanvasLabel);
});

$(document).on("click", ".table-list-mobile-item", function () {

    const dataOffcanvasTarget = $(this).data("offcanvas-target");

    if (!dataOffcanvasTarget) {
        return;
    }

    const offcanvasBottomInMobileLabel = $("#offcanvasBottomInMobileLabel");
    const dataOffcanvasLabel = $(this).find(".open-modal-label")?.text() || "";

    $("#offcanvasBottomInMobile .offcanvas-body")?.append(
        $(dataOffcanvasTarget).find(".inner-modal-in-mobile"),
    );

    $("#offcanvasBottomInMobile").attr(
        "data-destination-offcanvas-target",
        dataOffcanvasTarget,
    );

    offcanvasBottomInMobileLabel.text(dataOffcanvasLabel);
});

$(document).ready(function () {
    const offcanvasBottomInMobileElement = document.getElementById(
        "offcanvasBottomInMobile",
    );

    if (offcanvasBottomInMobileElement) {
        offcanvasBottomInMobileElement.addEventListener(
            "show.bs.offcanvas",
            function () {
                const fillterBoxContainerForm = $(
                    ".fillter-box-container form",
                );
                const fillterBoxContainerFormID =
                    fillterBoxContainerForm.attr("id");
                const offcanvasBodyForm = $(
                    "#offcanvasBottomInMobile form.offcanvas-body",
                );

                if (fillterBoxContainerFormID) {
                    fillterBoxContainerForm.removeAttr("id");
                    offcanvasBodyForm.attr("id", fillterBoxContainerFormID);
                }
            },
        );

        offcanvasBottomInMobileElement.addEventListener(
            "hidden.bs.offcanvas",
            function () {
                const $offcanvas = $(this);
                const dataDestinationOffcanvasTarget = $offcanvas.attr(
                    "data-destination-offcanvas-target",
                );

                if (dataDestinationOffcanvasTarget) {
                    $(dataDestinationOffcanvasTarget).append(
                        $offcanvas.find(
                            ".offcanvas-body .inner-modal-in-mobile",
                        ),
                    );
                }

                const offcanvasBodyForm = $offcanvas.find(
                    "form.offcanvas-body",
                );
                const offcanvasBodyFormID = offcanvasBodyForm.attr("id");
                const fillterBoxContainerForm = $(
                    ".fillter-box-container form",
                );

                if (offcanvasBodyFormID) {
                    offcanvasBodyForm.removeAttr("id");
                    fillterBoxContainerForm.attr("id", offcanvasBodyFormID);
                }
            },
        );
    }
});

