const handleRenderString = (
    menuItemLabel,
    renderSubmenuString,
    dataMenuItemCollapse,
) => {
    const renderString = `<div class="menu-item-collapse-container" data-menu-item-collapse="${dataMenuItemCollapse}">
                            <h5>${menuItemLabel}</h5>
                            <div class="wrapper-menu-item-collapse">
                                ${renderSubmenuString}
                            </div>
                        </div>`;

    return renderString;
};

const handlerenderSubmenuString = (
    dataHrefNavItem = "",
    icon,
    dataLabelNavItem,
    dataKeyNavItem = "",
) => {
    let url = new URL(dataHrefNavItem, window.location.origin);

    // added 2026-02-26, because mobile only support v1
    if (url.pathname.startsWith("/v2/m/")) {
        dataHrefNavItem = dataHrefNavItem.replace("/v2/m", "/m");
    }

    const extraClass =
        url.pathname === "/v2/report/end-day" ||
        url.pathname === "/report/end-day"
            ? "end_day_report"
            : "";

    const navKeyAttr = dataKeyNavItem
        ? ` data-nav-key="${dataKeyNavItem}"`
        : "";

    const renderString = `
        <a href="${dataHrefNavItem}" class="menu-item-collapse ${extraClass}"${navKeyAttr}>
            <div class="menu-item-svg">
                ${icon} 
            </div>
            <span>${dataLabelNavItem}</span>
        </a>
    `;
    return renderString;
};

const normalizePath = (path) => path.replace(/^\/v2/, "");

// Menu con active theo cả section (đồng bộ pattern system/parameter* ở header.blade.php)
const MOBILE_MENU_SECTION_PREFIXES = {
    general_settings: "/system/parameter",
};

const isPathInSection = (path, sectionPrefix) =>
    path === sectionPrefix || path.startsWith(`${sectionPrefix}/`);

const setActiveMenu = () => {
    const currentPath = normalizePath(window.location.pathname);

    $(".menu-item-collapse").each(function () {
        const href = this.getAttribute("href");
        if (!href || href === "#") return;

        const hrefPath = normalizePath(new URL(href, location.origin).pathname);
        const sectionPrefix =
            MOBILE_MENU_SECTION_PREFIXES[this.dataset.navKey];

        if (currentPath === hrefPath) {
            this.classList.add("active");
            return;
        }

        if (sectionPrefix && isPathInSection(currentPath, sectionPrefix)) {
            this.classList.add("active");
        }
    });
};

