// new custom pagin
const pagination = () => {
    const windowWidth = $(window).width();

    $(".form_pagi").each(function () {
        const $pagination = $(this).find(".pagination");
        $pagination.find(".page-item").show();
        $pagination.find(".dots-item").remove();

        const $items = $pagination.find(".page-item");
        const $pages = $items.not(":first-child, :last-child");

        const total = $pages.length;

        if (total <= 8) return;

        // tìm current page
        const currentIndex = $pages.index($pages.filter(".active"));

        // ẩn tất cả
        $pages.hide();

        // Hiển thị trang đầu, cuối
        const $firstPage = $pages.first().show();
        const $lastPage = $pages.last().show();

        // hiện current ±1
        const start = Math.max(currentIndex - 1, 1);
        const end = Math.min(currentIndex + 1, total - 2);

        const $middlePages = $pages.slice(start, end + 1).show();

        // thêm dấu ... đầu
        if (start > 1) {
            const $dotsStart = $(
                '<li class="page-item disabled dots-item"><span class="page-link">...</span></li>',
            );
            $middlePages.first().before($dotsStart);
        }

        // thêm dấu ... cuối
        if (end < total - 2) {
            const $dotsEnd = $(
                '<li class="page-item disabled dots-item"><span class="page-link">...</span></li>',
            );
            $middlePages.last().after($dotsEnd);
        }
    });
};

function initSlider(target) {
    let swiped = false;
    let startOffset = 0;
    const decelerationOnOverflow = 4;
    const revealWidth = 146;
    const snapWidth = revealWidth / 1.5;

    $(target).on("mousedown touchstart", function (event) {
        startOffset = 0;
        const startX = event.originalEvent.touches
            ? event.originalEvent.touches[0].clientX
            : event.clientX;

        $(document).on("mousemove touchmove", function (event) {
            const moveX =
                (event.originalEvent.touches
                    ? event.originalEvent.touches[0].clientX
                    : event.clientX) - startX;
            // const newX = getX(startOffset + moveX);
            const newX = Math.min(0, getX(startOffset + moveX));
            $(target).css("transform", "translateX(" + newX + "px)");
            if (newX >= snapWidth || newX <= -snapWidth) {
                swiped = newX < 0 ? -revealWidth : 0;
            } else {
                swiped = false;
            }
        });

        $(document).on("mouseup touchend", function () {
            $(document).off("mousemove touchmove");
            $(document).off("mouseup touchend");

            $(target).css("transition", "transform .2s ease-in");
            if (!swiped) {
                startOffset = 0;
                $(target).css("transform", "none");
            } else {
                startOffset = swiped;
                $(target).css("transform", "translateX(" + swiped + "px)");
            }
        });
    });

    $(target).on("dblclick", function () {
        $(target).css("transition", "transform .2s ease-in");
        swiped = false;
        startOffset = 0;
        $(target).css("transform", null);
    });

    function getX(x) {
        if (x < revealWidth && x > -revealWidth) {
            return x;
        }
        if (x < -revealWidth) {
            return (x + revealWidth) / decelerationOnOverflow - revealWidth;
        }
        if (x > revealWidth) {
            return (x - revealWidth) / decelerationOnOverflow + revealWidth;
        }
    }
}

