const escapeAttrForMobileList = (s) =>
    String(s ?? "")
        .replace(/&/g, "&amp;")
        .replace(/"/g, "&quot;")
        .replace(/</g, "&lt;")
        .replace(/'/g, "&#39;");

function renderStatus(status) {
    switch (Number(status)) {
        case 0:
            return '<span class="text-success fw-bold">Đã thanh toán</span>';
        case 1:
            return '<span class="fw-bold">Chưa thanh toán</span>';
        case 2:
            return '<span class="text-primary fw-bold">Thanh toán một phần</span>';
        case 3:
            return '<span class="text-warning fw-bold">Trả hàng</span>';
        case 4:
            return '<span class="text-danger fw-bold">Đã hủy</span>';
        default:
            return '<span class="fw-bold">Không xác định</span>';
    }
}

