// ==================================================================== //

function getCookie(name) {
    const cookies = document.cookie.split(";"); // Split the cookie string into an array
    for (let i = 0; i < cookies.length; i++) {
        let cookie = cookies[i].trim(); // Remove leading/trailing whitespace
        // Check if the cookie starts with the requested name
        if (cookie.startsWith(name + "=")) {
            return cookie.substring(name.length + 1); // Return the cookie's value
        }
    }
    return null; // Return null if the cookie is not found
}

// Block scope: order-cashier.js declares the same consts at top level; without
// this block script.js fails to parse when both files load on the same page.
{
    const enableVirtualKeyboard = getCookie("enable-virtual-keyboard") === "true";

    if (enableVirtualKeyboard) {
        $("#enable-virtual-keyboard").prop("checked", true);
    }

    const enableVirtualKeyboardEl = $("#enable-virtual-keyboard");

    enableVirtualKeyboardEl.on("change", function () {
        const isChecked = $("#enable-virtual-keyboard").is(":checked");
        document.cookie = `enable-virtual-keyboard=${isChecked}; path=/; max-age=${
            60 * 60 * 24 * 30
        }`;
    });
}

/**
 * ============================================================================
 * Máy bắn barcode: chặn Enter chọn nhầm dòng đầu trong select2
 * ============================================================================
 * Máy bắn gõ hết chuỗi rồi Enter trong vài mili-giây, nhanh hơn debounce ajax
 * của select2 (màn nhập kho / điều chỉnh kho để delay 200ms). Ngay lúc Enter,
 * dropdown VẪN đang là kết quả của lần tìm TRƯỚC, mà select2 luôn tô sáng sẵn
 * dòng đầu => Enter chọn nhầm sang một hàng hoá khác.
 *
 * Cách chặn: so mốc thời gian "từ khoá vừa đổi" với "danh sách vừa render lại".
 * Từ khoá mới hơn danh sách nghĩa là danh sách đang hiển thị vẫn của từ khoá CŨ
 * => huỷ việc chọn.
 *
 * Dùng select2:selecting vì đây là event CÔNG KHAI và HUỶ ĐƯỢC bằng
 * preventDefault (xem mảng preventableEvents trong js/libs/select2.min.js), nhờ
 * vậy không phải tranh thứ tự handler keydown với select2 và không phụ thuộc
 * thuộc tính nội bộ nào của thư viện.
 *
 * Không cần phân biệt select2 loại ajax hay tĩnh: loại tĩnh lọc đồng bộ, render
 * lại ngay khi gõ nên mốc render luôn mới hơn hoặc bằng mốc gõ => không bao giờ
 * bị chặn. Thêm chốt 1 giây phòng khi không bắt được lần render nào, tránh khoá
 * cứng phím Enter.
 */
(function () {
    if (
        typeof jQuery === "undefined" ||
        typeof MutationObserver === "undefined"
    ) {
        return;
    }

    var $ = jQuery;
    var STALE_GUARD_MS = 5000;
    var termChangedAt = 0;
    var resultsRenderedAt = 0;

    // CHỈ tính là "kết quả mới" khi có dòng THẬT được thêm vào danh sách.
    // Lúc bắt đầu tìm, select2 chèn thêm dòng "Đang tìm..." (class loading-results)
    // lên đầu mà KHÔNG xoá danh sách cũ (this.$results.prepend trong select2.min.js).
    // Nếu tính cả dòng đó thì tưởng nhầm danh sách đã mới -> guard mất tác dụng,
    // đúng lỗi máy bắn barcode vẫn chọn dòng đầu của kết quả cũ.
    var observer = new MutationObserver(function (mutations) {
        for (var i = 0; i < mutations.length; i++) {
            var added = mutations[i].addedNodes;

            for (var j = 0; j < added.length; j++) {
                var node = added[j];

                if (node.nodeType !== 1) {
                    continue;
                }

                if (
                    node.classList &&
                    node.classList.contains("loading-results")
                ) {
                    continue; // chỉ là dòng "Đang tìm...", chưa phải kết quả
                }

                resultsRenderedAt = Date.now();
                return;
            }
        }
    });

    $(document).on("select2:open", function () {
        observer.disconnect();
        termChangedAt = 0;
        resultsRenderedAt = Date.now();

        // .select2-results (không phải __options) để bắt được cả khi select2
        // thay nguyên khối danh sách chứ không chỉ thêm/bớt dòng
        var results = document.querySelector(
            ".select2-container--open .select2-results",
        );
        if (results) {
            observer.observe(results, { childList: true, subtree: true });
        }
    });

    $(document).on("select2:close", function () {
        observer.disconnect();
        termChangedAt = 0;
        resultsRenderedAt = 0;
    });

    $(document).on("input", ".select2-search__field", function () {
        termChangedAt = Date.now();
    });

    $(document).on("select2:selecting", function (e) {
        var field = document.querySelector(
            ".select2-container--open .select2-search__field",
        );

        // Không gõ gì thì giữ nguyên hành vi cũ
        if (!field || !(field.value || "").trim()) {
            return;
        }

        if (
            termChangedAt > resultsRenderedAt &&
            Date.now() - termChangedAt < STALE_GUARD_MS
        ) {
            e.preventDefault();
        }
    });
})();
